"""Export the frozen belief and distilled joint candidate; no optimizer/teacher ships."""
import argparse, base64, copy, hashlib, importlib.util, json
from pathlib import Path
import numpy as np
spec = importlib.util.spec_from_file_location('joint', Path(__file__).with_name('train-joint.py')); joint = importlib.util.module_from_spec(spec); spec.loader.exec_module(joint)

def read(p): return json.loads(Path(p).read_text())
def write(p, v): Path(p).parent.mkdir(parents=True, exist_ok=True); Path(p).write_text(json.dumps(v, ensure_ascii=False, separators=(',', ':'), allow_nan=False)+'\n')
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def pack(model):
    m = copy.deepcopy(model); n = m['network']; width = len(n['mean']); hidden = len(n['b1']); output = len(n['b2']); assert hidden <= 32
    data = b''.join(np.asarray(n[k], dtype='<f4').tobytes() for k in ['mean', 'scale'])+b''.join(np.asarray(n[k], dtype='<f2').tobytes() for k in ['w1', 'b1', 'w2', 'b2']); checksum = 0x811c9dc5
    for b in data: checksum = ((checksum ^ b)*0x01000193) & 0xffffffff
    m['network'] = dict(format='haiyue.small-fp16/1', input=width, hidden=hidden, output=output, byteLength=len(data), checksum=checksum, payload=base64.b64encode(data).decode())
    quantized = copy.deepcopy(model)
    for k in ['mean', 'scale']: quantized['network'][k] = np.asarray(n[k], dtype=np.float32).astype(float).tolist()
    for k in ['w1', 'b1', 'w2', 'b2']: quantized['network'][k] = np.asarray(n[k], dtype=np.float16).astype(float).tolist()
    return m, quantized
def main():
    ap = argparse.ArgumentParser(); ap.add_argument('--base', default='artifacts/guobiao-mahjong/league'); args = ap.parse_args(); base = Path(args.base); game = Path(__file__).resolve().parent.parent
    belief = read(base/'belief-v1/belief.json'); model = read(base/'student-v1/model.json'); bp, bq = pack(belief); jp, jq = pack(model)
    asset = game/'ai/joint/candidate.json'; write(asset, dict(format='haiyue.joint-bundle/1', belief=bp, joint=jp)); digest = sha(asset)
    (game/'ai/joint/asset.ts').write_text('// Generated by benchmarks/export-joint.py. Experimental; qualification is recorded separately.\nexport const JOINT_ASSET='+json.dumps(dict(name='joint-candidate-v1.json', size=asset.stat().st_size, sha256=digest), separators=(',', ':'))+' as const;\n')
    rows = []; deltas = []; agreements = []
    for row in read(base/'student-v1/parity.json'):
        f = np.asarray(row['features']); parents = np.asarray(row['parents']); prior = np.asarray(row['prior']); z, _ = joint.logits(joint.core.normalize(f, np.asarray(jq['network']['mean']), np.asarray(jq['network']['scale'])), joint.unpack(jq)); p, _ = joint.distribution(z[:, 0], parents, prior, row['temperature']); full, _ = joint.logits(joint.core.normalize(f, np.asarray(model['network']['mean']), np.asarray(model['network']['scale'])), joint.unpack(model)); deltas.append(float(np.abs(z-full).max())); agreements.append(joint.parent_best(z[:, 0], parents, prior) == joint.parent_best(full[:, 0], parents, prior)); rows.append({**row, 'predictions': joint.outputs(z).tolist(), 'probabilities': p.tolist()})
    beliefs = []
    for row in read(base/'belief-v1/parity.json'):
        # Reference feature extraction itself is tested separately against the public observation.
        f = np.asarray(row['features']); n = bq['network']; z, _ = joint.logits(joint.core.normalize(f.reshape(1, -1), np.asarray(n['mean']), np.asarray(n['scale'])), joint.unpack(bq)); p = joint.core.sigmoid(z[0]/np.asarray(bq['calibration']['temperature'])+np.asarray(bq['calibration']['bias'])); beliefs.append({**row, 'probabilities': p.tolist()})
    fixture = game.parent/'test/fixtures/mahjong-joint-model.json'; write(fixture, dict(assetSha256=digest, joint=rows, belief=beliefs))
    report = dict(schemaVersion=1, status='passed', role='experimental-browser-candidate', assetSha256=digest, sourceBytes=asset.stat().st_size, networkPayloadBytes=bp['network']['byteLength']+jp['network']['byteLength'], beliefSha256=sha(base/'belief-v1/belief.json'), studentSha256=sha(base/'student-v1/model.json'), teacherSha256=read(base/'student-v1/report.json')['teacherSha256'], fixtureSha256=sha(fixture), parityMaximumLogitQuantizationError=max(deltas), parityPlanAgreement=float(np.mean(agreements)), limitation='Quantization parity is not a playing-strength qualification; original/default model remains available')
    write(base/'export-v1/report.json', report); write(base/'export-v1/joint-quantized.json', jq); write(base/'export-v1/belief-quantized.json', bq); (base/'export-v1/exporter.py').write_bytes(Path(__file__).read_bytes()); print(json.dumps(report, indent=2))
if __name__ == '__main__': main()
